// The Stralog section's playground (stralog/, generated by
// doc/manual/gen/genstralog.py): StrataOS in the WebAssembly emulator, booted
// from the play page's boot ROM and disk image, with `-m 8 stralog` typed at
// the shell's first prompt. It shares the play page's machinery rather than
// copying it: the worker (../play/worker.js, which owns the emulator and
// speaks the protocol documented at its top), the module
// (../play/strata-emu.wasm), the images and the examples come from
// ../play/. This file moves bytes: console output to the terminal, keys,
// "Try" queries and consulted clauses to the worker.
"use strict";
(function () {
  // tools/web-stamp.sh puts the build id here; every asset URL carries it
  const BUILD = "__BUILD__";
  const V = "?v=" + BUILD;
  const PLAY = "../play/";
  const params = new URLSearchParams(location.search);
  // The JIT as on the play page (../play/jit.js)
  const JIT_LIMITS = StrataJIT.LIMITS;
  const jitStart = StrataJIT.choose(params);
  let jitOn = jitStart.on;
  const args = () => [jitOn ? "-J" : "-j", "-c", "12", "-d", "disk.img", "bootrom.stx"];
  const START = "-m 8 stralog\n";          // typed at the shell's first prompt

  const $ = (id) => document.getElementById(id);
  const pg = $("pg"), toggle = $("pg-toggle"), statusEl = $("pg-status");
  const enc = new TextEncoder(), dec = new TextDecoder();
  const wide = () => matchMedia("(min-width: 1280px)").matches;
  const touch = () => matchMedia("(pointer: coarse)").matches;

  // -------------------------------------------------------------- terminal
  const term = new Terminal({
    convertEol: true, cursorBlink: true, scrollback: 5000,
    fontFamily: '"JetBrains Mono", ui-monospace, Menlo, monospace', fontSize: 13,
    theme: {
      background: "#05080f", foreground: "#cfe8ff", cursor: "#ffb347", cursorAccent: "#05080f",
      selectionBackground: "rgba(77, 225, 255, 0.3)",
      black: "#0b1120", red: "#ff6b6b", green: "#5be3a1", yellow: "#ffb347", blue: "#4d8dff",
      magenta: "#c38bff", cyan: "#4de1ff", white: "#cfe8ff",
      brightBlack: "#5b7088", brightRed: "#ff8f8f", brightGreen: "#8af0bf", brightYellow: "#ffd08a",
      brightBlue: "#7fb0ff", brightMagenta: "#dab4ff", brightCyan: "#9bf0ff", brightWhite: "#ffffff",
    },
  });
  const fit = new FitAddon.FitAddon();
  term.loadAddon(fit);
  term.open($("pg-term"));
  function refit() {
    if (!$("pg-term").offsetHeight) return; // the drawer is closed
    try { fit.fit(); } catch (e) { /* not laid out yet */ }
    term.scrollToBottom();
  }
  document.fonts.load('13px "JetBrains Mono"').then(() => document.fonts.ready).then(() => {
    const f = term.options.fontFamily;
    term.options.fontFamily = "monospace";
    term.options.fontFamily = f;
    refit();
  });
  new ResizeObserver(refit).observe($("pg-term"));
  term.writeln("\x1b[36mStralog\x1b[0m in StrataOS, in the WebAssembly emulator: press Try on an example, or type a query.");

  // -------------------------------------------------------------- the machine
  // Three stages: booting (until the shell's prompt), starting stralog
  // (until its first ?- prompt), ready. What is sent before it is ready
  // waits in `pending`.
  let W = null, stopped = true, pending = "", booted = false, gen = 0;
  let stage = 0, tail = "";
  let last = { t: 0, steps: 0 };

  let wasmModule = null;
  async function compileWasm() {
    if (wasmModule) return wasmModule;
    try {
      wasmModule = await WebAssembly.compileStreaming(fetch(PLAY + "strata-emu.wasm" + V));
    } catch (e) { // a server without application/wasm
      wasmModule = await WebAssembly.compile(await (await fetch(PLAY + "strata-emu.wasm" + V)).arrayBuffer());
    }
    return wasmModule;
  }
  const images = {};
  function fetchImage(name) {
    if (!images[name]) images[name] = fetch(PLAY + "images/" + name + V).then((r) => {
      if (!r.ok) throw new Error("images/" + name + ": " + r.status);
      return r.arrayBuffer();
    });
    return images[name];
  }

  function setStatus(s, isStop) {
    statusEl.textContent = s;
    statusEl.classList.toggle("stopped", !!isStop);
    if (isStop) StrataJIT.disarm();
  }

  function post(s) {
    let bytes = [];
    for (const ch of s) for (const b of enc.encode(ch === "\r" ? "\n" : ch)) bytes.push(b);
    if (bytes.length) W.postMessage({ t: "input", data: new Uint8Array(bytes) });
  }
  // Bytes for the console: straight there once stralog runs; until then they wait
  function send(s) {
    if (W && !stopped && stage === 2) post(s);
    else { pending += s; boot(); }
  }
  // keys typed into the terminal go through at any stage (the shell, a question)
  function key(s) {
    if (W && !stopped) post(s);
    else { pending += s; boot(); }
  }

  function onOutput(w, data) {
    term.write(data, () => term.scrollToBottom());
    if (stage === 2) return;
    tail = (tail + dec.decode(data)).slice(-16);
    if (stage === 0 && tail.includes("strata$ ")) {      // the shell: start stralog
      stage = 1; tail = "";
      post(START);
    } else if (stage === 1 && tail.includes("?- ")) {    // stralog's first prompt
      stage = 2;
      setStatus("running · StrataOS, 12 cores · stralog");
      if (pending) { post(pending); pending = ""; }
    }
  }

  function onWorker(w, m) {
    if (w !== W) return;
    switch (m.t) {
    case "out": onOutput(w, m.data); break;
    case "started":
      last = { t: performance.now(), steps: 0 };
      setStatus("booting StrataOS…");
      break;
    case "status": {
      if (stage < 2) break;
      const t = performance.now();
      const mips = (m.steps - last.steps) / ((t - last.t) * 1000);
      last = { t, steps: m.steps };
      setStatus(`running · ${m.live}/${m.cores} cores live · ` +
                (mips >= 1 ? `${mips.toFixed(0)} MIPS (${m.jit ? "JIT" : "interpreter"})` : "waiting for input") +
                ` · ${(m.steps / 1e6).toFixed(1)}M instructions`);
      break;
    }
    case "stopped":
      stopped = true;
      setStatus((m.state === 1 ? (m.faulted ? "halted: a core faulted" : "every core halted")
                 : m.state === 2 ? "deadlock" : "stopped") + " · Reset to boot again", true);
      break;
    case "exit": stopped = true; setStatus(`exited (${m.code}) · Reset`, true); break;
    case "error": stopped = true; setStatus("error: " + m.msg, true); break;
    }
  }

  async function boot() {
    if (booted) return;
    booted = true;
    const my = ++gen;
    stage = 0; tail = "";
    setStatus("loading…");
    term.write("\x1bc");
    term.write(`\x1b[2m$ strata-emu ${args().join(" ")}\x1b[0m\n`);
    try {
      const [wasm, rom, disk] = await Promise.all([compileWasm(), fetchImage("bootrom.stx"), fetchImage("disk.img")]);
      if (my !== gen) return;               // Reset meanwhile
      const w = new Worker(PLAY + "worker.js" + V);
      W = w;
      stopped = false;
      w.onmessage = (e) => onWorker(w, e.data);
      w.onerror = (e) => { if (w === W) { stopped = true; setStatus("error: " + (e.message || "the worker failed"), true); } };
      if (jitOn) StrataJIT.arm();
      // (the worker keeps the disk image as it is given: a copy, so that Reset starts from the original)
      w.postMessage(Object.assign({ t: "start", wasm,
        files: [{ name: "bootrom.stx", data: rom }, { name: "disk.img", data: disk.slice(0) }], args: args() }, JIT_LIMITS));
    } catch (e) {
      booted = false;
      setStatus("error: " + (e && e.message ? e.message : e), true);
    }
  }

  function reset() {
    if (W) W.terminate();
    W = null;
    StrataJIT.disarm();
    stopped = true;
    booted = false;
    pending = "";
    boot();
  }

  // -------------------------------------------------------------- the drawer
  function isOpen() { return wide() || pg.classList.contains("open"); }
  function setOpen(on) {
    pg.classList.toggle("open", on);
    toggle.setAttribute("aria-expanded", String(on || wide()));
    toggle.querySelector(".pg-title").textContent = (on || wide() ? "▾" : "▸") + " PLAYGROUND";
    if (on || wide()) { requestAnimationFrame(refit); boot(); }
  }
  toggle.addEventListener("click", () => { if (!wide()) setOpen(!pg.classList.contains("open")); });
  addEventListener("resize", () => setOpen(pg.classList.contains("open")));
  for (const b of document.querySelectorAll("[data-pg-open]"))
    b.addEventListener("click", () => { setOpen(true); term.focus(); });
  setOpen(false);                            // wide: open, and boots now

  // -------------------------------------------------------------- input
  term.onData((d) => { term.scrollToBottom(); key(d); });
  $("pg-reset").addEventListener("click", () => { reset(); if (!touch()) term.focus(); });
  if (jitStart.note) {
    $("pg-jitnote-t").textContent = jitStart.note;
    $("pg-jitnote").hidden = false;
    $("pg-jit-on").addEventListener("click", () => {
      StrataJIT.forget();
      jitOn = true;
      $("pg-jitnote").hidden = true;
      reset();
    });
  }

  // -------------------------------------------------------------- the editor
  // A textarea over a <pre>, as on the Forth page; the text is kept per
  // browser (localStorage). Consult sends it as [user]. ... Ctrl-D.
  const src = $("pg-src"), hlEl = $("pg-ed-hl");
  const KEY = "strata-prolog-editor";
  const SAMPLE = "% Edit, then Consult (Ctrl+Enter); then ask in the terminal,\n" +
    "% or put the cursor on a query below and press Ask line.\n" +
    "likes(mary, wine).\nlikes(john, wine).\nlikes(john, mary).\n" +
    "friends(X, Y) :- likes(X, Z), likes(Y, Z), X \\== Y.\n" +
    "% ?- friends(mary, Who).\n";
  const norm = (s) => s.replace(/\r\n?/g, "\n");
  const escH = (s) => s.replace(/[&<>]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" })[c]);
  let hlQueued = false, saveTimer = 0;
  function highlight() {
    hlQueued = false;
    hlEl.innerHTML = (window.StrataHL ? StrataHL.plLines(src.value.split("\n")).join("\n") : escH(src.value)) + "\n ";
    fitSource();
  }
  const pre = hlEl.parentElement;
  function fitSource() {
    const r = pre.getBoundingClientRect();
    src.style.width = r.width + "px";
    src.style.height = r.height + "px";
  }
  new ResizeObserver(fitSource).observe($("pg-ed"));
  function changed() {
    if (!hlQueued) { hlQueued = true; requestAnimationFrame(highlight); }
    clearTimeout(saveTimer);
    saveTimer = setTimeout(() => { try { localStorage.setItem(KEY, src.value); } catch (e) { /* no storage */ } }, 300);
  }
  function load(text) {
    text = norm(text);
    src.value = text;
    src.setSelectionRange(0, 0);
    src.scrollTop = 0;
    $("pg-ed").scrollTop = 0;
    changed();
  }
  try { const t = localStorage.getItem(KEY); src.value = t === null ? SAMPLE : t; } catch (e) { src.value = SAMPLE; }
  highlight();
  src.addEventListener("input", changed);

  function consult() {
    const text = norm(src.value);
    if (!text.trim()) return;
    if (!isOpen()) setOpen(true);
    // (a newline first: it ends an answer still waiting for ; and is
    // nothing at the ?- prompt)
    send("\n[user].\n" + (text.endsWith("\n") ? text : text + "\n") + "\x04");
    term.scrollToBottom();
  }
  function askLine() {
    const v = src.value;
    let a = src.selectionStart, b = src.selectionEnd;
    a = v.lastIndexOf("\n", a - 1) + 1;
    const e = v.indexOf("\n", b);
    let line = v.slice(a, e < 0 ? v.length : e).replace(/^\s*%\s*/, "").replace(/^\?-\s*/, "").trim();
    if (!line) return;
    if (!line.endsWith(".")) line += ".";
    if (!isOpen()) setOpen(true);
    send("\n" + line + "\n");
  }
  $("pg-run").addEventListener("click", consult);
  $("pg-ask").addEventListener("click", askLine);
  const mac = /Mac|iPhone|iPad/.test(navigator.platform || navigator.userAgent);
  $("pg-key").textContent = (mac ? "⌘" : "Ctrl+") + "Enter";
  src.addEventListener("keydown", (e) => {
    if (e.key === "Enter" && (e.ctrlKey || e.metaKey)) { e.preventDefault(); consult(); }
  });

  // Try: consult the example from the disk and ask its query
  document.addEventListener("click", (e) => {
    const b = e.target.closest(".try-b");
    if (b) {
      if (!isOpen()) setOpen(true);
      send("\n" + b.dataset.try + "\n");
      b.classList.add("sent");
      setTimeout(() => b.classList.remove("sent"), 600);
      if (!touch()) term.focus({ preventScroll: true });
      return;
    }
    const ed = e.target.closest(".ex-edit");
    if (ed) loadExample(ed.dataset.edit);
  });

  // the examples (lang/stralog/examples/*.pl, put under stralog/ by make wasm)
  async function loadExample(name) {
    if (!isOpen()) setOpen(true);
    const r = await fetch(PLAY + "stralog/" + name + ".pl" + V);
    if (r.ok) load(await r.text());
  }
  const demos = $("pg-demos");
  fetch(PLAY + "stralog/index.txt" + V).then((r) => (r.ok ? r.text() : "")).then((txt) => {
    for (const name of txt.split(/\s+/).filter(Boolean)) {
      const o = document.createElement("option");
      o.value = name;
      o.textContent = name + ".pl";
      demos.appendChild(o);
    }
  });
  demos.addEventListener("change", () => {
    const name = demos.value;
    demos.value = "";
    if (name) loadExample(name);
  });
})();
